import{_ as o,l as s,o as t,c as h,v as n,p as i,x as l,d,i as m,S as _,b as e}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"头维度对头数","description":"","frontmatter":{"title":"头维度对头数","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/head-dim-vs-heads.md","filePath":"llm/head-dim-vs-heads.md","lastUpdated":1789023840000}'),p={name:"llm/head-dim-vs-heads.md"};function A(E,a,k,c,u,B){const r=s("Mermaid");return t(),h("div",null,[a[1]||(a[1]=n('<h1 id="头维度对头数" tabindex="-1">头维度对头数 <a class="header-anchor" href="#头维度对头数" aria-label="Permalink to &quot;头维度对头数&quot;">​</a></h1><div class="epigraph"><p>多头把 $d_{\\mathrm{model}}$ 切开并行路由；头数与每头维度的乘积被宽度钉死，多一头就薄一头。</p><footer>—— Vaswani et al., Attention Is All You Need, NeurIPS 2017；头可剪枝的实证见 Michel et al., Are Sixteen Heads Really Better than One?, NeurIPS 2019</footer></div><p><a href="/llm/multi-token-attention">上一课</a>让单头的 \\(q,k\\) 先带上局部邻居，但仍假定头数与 \\(d_k\\) 已经选好。主干 <a href="/llm/mha">多头</a> 写过 \\(d_{\\mathrm{model}}=h\\cdot d_k\\) 的切分，没有把这对超参当成课序里的对象。本课补：宽度固定时，多头还是厚头，并对照 <a href="/llm/gqa">GQA</a> 的 KV 头。后课长度缩放假定 \\(d_k\\) 已知，因为温度与 \\(\\sqrt{d_k}\\) 绑在一起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Vaswani 等人取 \\(h=8\\)、\\(d_k=64\\)。更宽的模型习惯保持 \\(d_k=128\\) 左右加头，而不是把 \\(d_k\\) 加到 512。Michel 等人又显示许多头可以在推理时关掉。缺口是一条设计约束：<strong>头数管的是并行的路由条数，头维管的是每条路由的点积分辨率</strong>，二者在固定 \\(d_{\\mathrm{model}}\\) 下互为代价，不能同时拉满。</p><p><a href="/llm/gated-attention">门控注意力</a> 按头关断、CLA 按层共享 KV，都默认头已经切好。切错了，后面的共享与门都在错误的粒度上操作。</p><p><span class="marginnote">\\(d_k\\) 进入 <a href="/llm/sdpa">SDPA</a> 的 \\(\\sqrt{d_k}\\)。改头维不只改表达力，也改默认温度。比较头数时要控制缩放，否则在比两件不同的数值设定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 \\(d_{\\mathrm{model}}\\)，选 \\(h\\) 使 \\(d_k=d_{\\mathrm{model}}/h\\) 整除（或允许投影把头拼接维与模型维解开，此时参数量另计）。查询头可以多于 KV 头：GQA 令 \\(h_{\\mathrm{kv}}\\lt h_q\\)，\\(d_k\\) 仍按查询头切。评测应在相同 FLOPs 或相同参数下扫 \\((h,d_k)\\)，而不是只报一个最大 \\(h\\)。</p><p>实践区间：\\(d_k\\in[64,256]\\) 居多。过小，点积分辨率不够，头再多也是噪声路由；过大，头数不够，无法同时维持多种读模式，多头名不副实。Michel 的剪枝说明训练可以养冗余头——那是优化动态，不是说设计时该把 \\(h\\) 加到极限再靠剪枝。</p><h3 id="与宽度缩放的耦合" tabindex="-1">与宽度缩放的耦合 <a class="header-anchor" href="#与宽度缩放的耦合" aria-label="Permalink to &quot;与宽度缩放的耦合&quot;">​</a></h3><p>加宽 \\(d_{\\mathrm{model}}\\) 时有两条惯用路径：保持 \\(d_k\\) 加 \\(h\\)，或保持 \\(h\\) 加 \\(d_k\\)。前者增加路由条数，后者增加每条的容量。GQA/MQA 出现后，第三条是 \\(h_q\\) 随宽度涨、\\(h_{\\mathrm{kv}}\\) 涨得更慢，把缓存从这条乘法里解开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个头是一个低维内容寻址器。\\(d_k\\) 太小，键空间碰撞多，不同模式挤在同一点积里。\\(h\\) 太小，所有模式必须挤进少数子空间，残差流里的叠加更严重。多头的本意是让 softmax 在不同子空间里各自尖峰；头维则保证尖峰所在的空间还能分得清键。</p><p>推理剪枝能去掉的头，往往是从未学到独特路由的副本。训练时保留它们可能有助于优化的随机性，部署时不该把「可剪」理解成「当初不该存在」——那是另一笔计算账。</p><p><span class="marginnote">输出投影把 \\(h\\cdot d_v\\) 混回 \\(d_{\\mathrm{model}}\\)。头之间的交流只发生在这里和残差流，不发生在 softmax 内部。加头却不配足够的 \\(d_v\\)，输出投影变成瓶颈。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给封闭最优公式。任务若偏精确检索，略厚的 \\(d_k\\) 更稳；若偏多样路由（代码里同时要对齐括号、变量、缩进），略多的 \\(h\\) 更稳。硬件上 \\(d_k\\) 过小会让矩阵乘不饱满；\\(d_k=128\\) 常是吞吐与表达的折中，不是理论值。下一课的长度缩放会再乘一个与 \\(n\\) 有关的因子，不要在本课把 \\(\\sqrt{d_k}\\) 改成 \\(\\sqrt{n}\\)。</p>',18)),(t(),i(_,null,{default:l(()=>[m(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%9B%BA%E5%AE%9A%20d_model%22%5D%20--%3E%20H%5B%22%E5%A2%9E%E5%8A%A0%E5%A4%B4%E6%95%B0%20h%22%5D%0A%20%20D%20--%3E%20K%5B%22%E5%A2%9E%E5%8A%A0%E5%A4%B4%E7%BB%B4%20d_k%22%5D%0A%20%20H%20--%3E%20T%5B%22%E8%B7%AF%E7%94%B1%E6%9D%A1%E6%95%B0%E5%A4%9A%E3%80%81%E6%AF%8F%E6%9D%A1%E6%9B%B4%E8%96%84%22%5D%0A%20%20K%20--%3E%20R%5B%22%E5%88%86%E8%BE%A8%E7%8E%87%E9%AB%98%E3%80%81%E6%9D%A1%E6%95%B0%E5%B0%91%22%5D%0A%20%20T%20--%3E%20GQA%5B%22GQA%20%E5%86%8D%E6%94%B6%20KV%20%E5%A4%B4%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[d("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"固定宽度下头数与头维互为代价：前者是并行路由，后者是点积分辨率。"),e("li",null,"\\(d_k\\) 同时决定 SDPA 温度；比较结构时要控制缩放。"),e("li",null,"GQA 把缓存从查询头数上解开，不回答 \\(d_k\\) 该多大。"),e("li",null,"可剪枝不等于设计时该堆冗余头。"),e("li",null,"出处：Vaswani et al., NeurIPS 2017；Michel et al., NeurIPS 2019。")],-1))])}const D=o(p,[["render",A]]);export{q as __pageData,D as default};
